///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name findPosY
 * @description find Pos Y 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.findPosY = function (obj) {
    let curtop = 0;
    if (obj.offsetParent) {
        while (obj.offsetParent) {
            curtop += obj.offsetTop;
            obj = obj.offsetParent;
        }
    } else {
        if (obj.y) {
            curtop += obj.y;
        }
    }
    return curtop;
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @param {*} mode mode
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function (mode) {
    const f = (document.form || { elements: [] });
    if (($c.util.getComponent('ipt_name_2').getValue() == null ? '' : String($c.util.getComponent('ipt_name_2').getValue())) === '') {
        await $c.win.alert("성명을 입력해 주세요.");
        $c.util.getComponent("ipt_name_2").focus();
        return;
    }
    f.action = "/PersonInfo.do";
    $c.util.getComponent('dma_submitReq').set('method', "personSearchList");
    if ((String($c.util.getComponent('ipt_check1').getValue() || "") !== "")) {
        $c.util.getComponent("dma_submitReq").set("jrKind1", "00");
    }
    if ((String($c.util.getComponent('ipt_check2').getValue() || "") !== "")) {
        $c.util.getComponent("dma_submitReq").set("jrKind2", encodeURI("대표이사"));
    }
    if ((String($c.util.getComponent('ipt_check3').getValue() || "") !== "")) {
        $c.util.getComponent("dma_submitReq").set("jrKind3", "02");
    }
    if (mode == null) {
        $c.util.getComponent('dma_submitReq').set('newsScrollY', "");
        $c.util.getComponent('dma_submitReq').set('pageNum', "1");
    }
    $c.util.getComponent("ipt_name_2").setValue(encodeURI($c.util.getComponent('ipt_name_2').getValue()));
    $c.util.getComponent("dma_submitReq").set("birthday", $c.util.getComponent("dma_submitReq").get("birthday").replace(/\./g, ""));
    await scwin.tx_submit();

};

/**
 * @method
 * @name findSameName
 * @description find Same Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findSameName = async function () {
    if (($c.util.getComponent('ipt_name_2').getValue() == null ? '' : String($c.util.getComponent('ipt_name_2').getValue())) === '') {
        await $c.win.alert("이름을 입력하여 주세요.");
        return;
    }
    const f = (document.frm || { elements: [] });
    f.target = "REGULAR";
    $c.util.getComponent("ipt_name_2").setValue(encodeURI($c.util.getComponent('ipt_name_2').getValue()));
    $c.util.getComponent('dma_submitReq').set('method', "findSameName");
    await scwin.tx_findSameName();
};

/**
 * @method
 * @name searchPerson
 * @description search Person 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchPerson = async function () {
    let chgList;
    $c.util.getComponent("ipt_name_2").setValue(encodeURI($c.util.getComponent('ipt_name_2').getValue()));
    const strOptions = "width=430, height=300, toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=no";
    chgList = $c.win.openPopup("", String((typeof strOptions !== 'undefined' ? strOptions : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "chgList", width: "430", height: "300", scrollbars: true, resizable: false, type: "pageFramePopup" }, { id: '' }) : { id: "chgList", width: "430", height: "300", scrollbars: true, resizable: false, type: "pageFramePopup" }), {});
    (document.form2 || { elements: [] }).target = "chgList";
    await scwin.tx_searchPerson();
};

/**
 * @method
 * @name pageNav
 * @description page Nav 처리
 * @param {*} funcName funcName
 * @param {*} pageNum pageNum
 * @param {*} pageSize pageSize
 * @param {*} total total
 * @returns {void}
 * @hidden N
 */
scwin.pageNav = function (funcName, pageNum, pageSize, total) {
    if (total < 1) {
        return "";
    }
    let ret = "";
    const PAGEBLOCK = 10;
    const totalPages = Math.floor((total - 1) / pageSize) + 1;
    let firstPage = Math.floor((pageNum - 1) / PAGEBLOCK) * PAGEBLOCK + 1;
    if (firstPage <= 0) {
        firstPage = 1;
    }
    let lastPage = firstPage - 1 + PAGEBLOCK;
    if (lastPage > totalPages) {
        lastPage = totalPages;
    }
    if (firstPage > PAGEBLOCK) {
        ret += navAnchor(funcName, 1, "<<처음") + "&nbsp;\n";
        ret += navAnchor(funcName, (firstPage - 1), "<이전") + "&nbsp;\n";
    }
    for (i = firstPage; i <= lastPage; i++) {
        if (pageNum === i) {
            ret += "<a class='active' onclick='return false;' href='#page_link_" + 1 + "'>" + i + "</a>&nbsp;\n";
        } else {
            ret += navAnchor(funcName, i, i) + "&nbsp;\n";
        }
    }
    if (lastPage < totalPages) {
        ret += navAnchor(funcName, (lastPage + 1), "다음>") + "&nbsp;\n";
        ret += "&nbsp;" + navAnchor(funcName, totalPages, "끝>>") + "\n";
    }
    return ret;
};
